import { useState } from 'react';

type Props = { min?: number; max?: number; step?: number; initial?: number };

export default function {{component_name}}({ min = 0, max = 100, step = 1, initial = 50 }: Props) {
  const [v, setV] = useState(initial);
  return (
    <div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={v}
        onChange={(e) => setV(Number(e.target.value))}
        className="w-full"
      />
      <div className="text-sm text-gray-600">{v}</div>
    </div>
  );
}
